function isRedisEnabled() {
  return getRedisClient() !== null;
}

async function retrieveDataFromCache(key) {
  if (!isRedisEnabled()) return null; // Skip cache if Redis is not available

  const cacheKey = `${REDIS_PREFIX}:${key}`;
  const cachedData = await getRedisClient().get(cacheKey);
  if (cachedData) {
    return JSON.parse(cachedData);
  }
  return null;
}

async function storeDataInCache(key, data) {
  if (!isRedisEnabled()) return; // Skip cache if Redis is not available

  const cacheKey = `${REDIS_PREFIX}:${key}`;
  await getRedisClient().set(cacheKey, JSON.stringify(data));
}

async function deleteDataFromCache(key) {
  if (!isRedisEnabled()) return; // Skip cache if Redis is not available

  const cacheKey = `${REDIS_PREFIX}:${key}`;
  await getRedisClient().del(cacheKey);
}

cacheHandler = (key) => async (req, res, next) => {
  try {
    const cachedData = await retrieveDataFromCache(key);
    if (cachedData) {
      console.log(`Getting cached data for key: ${key}`);
      return res.status(HTTP_STATUS.OK).json(cachedData);
    }
    next(); // Proceed to the route handler if data is not cached
  } catch (err) {
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({ message: err.message });
  }
}

